  introActionSkip: ".no-main-intro-action__skip",
  contactText: ".no-main-contact .no-main-contact__head .mask-target",
};

const drawer = {
  selector: ".no-drawer",
  innerSelector: ".no-drawer__inner",
  revealGroups: [
    ".no-drawer__gnb",
    ".no-drawer__gnb-sub",
    ".no-drawer__address",
  ],
  gnbLinkSelector: ".no-drawer__gnb-link[href]",
  gnbSubLinkSelector: ".no-drawer__gnb-sub-link[href]",
} as const;

export const DOM_CONFIG: DomConfig = {
