@use "../abstract" as *;

// =============================================================================
// 코너 브라켓 — 모서리마다 정사각형 SVG (가로/세로 굵기·길이 동일, 마그네틱과 동일 느낌)
// =============================================================================

// 빛나는 코너 글로우 애니메이션 (선택 적용: .no-corner-bracket--shine)
@keyframes corner-bracket-glow {
  0%,
  100% {
    filter: drop-shadow(
        0 0 4px color-mix(in srgb, currentColor 45%, transparent)
      )
      drop-shadow(0 0 12px color-mix(in srgb, currentColor 25%, transparent));
  }
  50% {
    filter: drop-shadow(
        0 0 8px color-mix(in srgb, currentColor 55%, transparent)
      )
      drop-shadow(0 0 18px color-mix(in srgb, currentColor 35%, transparent));
  }
}

// 마그네틱 코너와 동일한 stroke 두께 (config MAGNETIC_CORNER_STROKE_WIDTH)
// --corner-bracket-size: JS에서 부모 크기 따라 유동 설정 (작은 버튼은 %로 축소)
.no-corner-bracket {
  --corner-glow-blur: 8px;
  --corner-glow-spread: 18px;
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  display: block;
  width: 100%;
  height: 100%;

  &__corner {
    position: absolute;
    width: var(--corner-bracket-size);
    height: var(--corner-bracket-size);
    color: inherit;
    transition: transform var(--transition-default);

    svg {
      display: block;
      width: 100%;
      height: 100%;
      stroke: currentColor;
      stroke-width: var(--corner-stroke-width);
      stroke-linecap: square;
      // 빛나는 글로우: 안쪽 강한 휘광 + 바깥 부드러운 번짐
      filter: drop-shadow(
          0 0 var(--corner-glow-blur)
            color-mix(in srgb, currentColor 50%, transparent)
        )
        drop-shadow(
          0 0 var(--corner-glow-spread)
            color-mix(in srgb, currentColor 22%, transparent)
        );
    }

    &--tl {
      left: 0;
      top: 0;
    }
    &--tr {
      right: 0;
      top: 0;
    }
    &--bl {
      left: 0;
      bottom: 0;
    }
    &--br {
      right: 0;
      bottom: 0;
    }
  }

  // 반짝이는 애니메이션 적용 (버튼 등에 no-corner-bracket--shine 추가 시)
  &--shine &__corner svg {
    animation: corner-bracket-glow 2.5s ease-in-out infinite;
  }
}

